17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.Collections;
22	import java.util.List;
23	import java.util.Map;
24	import java.util.Objects;
25	import java.util.stream.Collectors;
26	
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
110	        if (ownerAlreadyExists(owner) || emailAlreadyExists(owner)) {
111	            return new ResponseEntity<>(HttpStatus.CONFLICT);
112	        }
113	        if (dailyRegistrationLimitReached()) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        if (cityAtCapacity(owner.getCity())) {
117	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
118	        }
119	        if (owner.getRegistrationDate() == null) {
120	            owner.setRegistrationDate(LocalDate.now());
121	        }
122	        owner.setCity(resolveCity(owner.getCity()));
123	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
124	        owner.setMembershipNumber(membershipNumber);
125	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
126	        owner.setMembershipTier(membershipTierFor(membershipNumber));
127	        owner.setNamesakeCount(namesakeCount(owner.getLastName()));
128	        owner.setSharesHousehold(sharesHousehold(owner));
129	        owner.setLocality(localityFor(owner.getCity()));
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    /**
138	     * The maximum number of owners that may be registered on any single day (by registration date).
139	     */
140	    private static final long MAX_OWNERS_PER_DAY = 20;
141	
142	    /**
143	     * Determines whether the maximum number of owners for the current day has already been reached.
144	     * Owners are counted by their registration date, so once {@value #MAX_OWNERS_PER_DAY} owners
145	     * carry today's registration date no further owners may be created today.
146	     *
147	     * @return {@code true} if today's registration limit has been reached
148	     */
149	    private boolean dailyRegistrationLimitReached() {
150	        LocalDate today = LocalDate.now();
151	        long registeredToday = this.clinicService.findAllOwners().stream()
152	            .filter(existing -> today.equals(existing.getRegistrationDate()))
153	            .count();
154	        return registeredToday >= MAX_OWNERS_PER_DAY;
155	    }
156	
157	    /**
158	     * The maximum number of owners that may be registered in any single city.
159	     */
160	    private static final long MAX_OWNERS_PER_CITY = 8;
161	
162	    /**
163	     * Determines whether the given city has already reached its capacity of
164	     * {@value #MAX_OWNERS_PER_CITY} owners. Owners are counted per city ignoring letter case, so
165	     * once a city holds {@value #MAX_OWNERS_PER_CITY} owners no further owners may be created there.
166	     *
167	     * @param city the raw city supplied for the owner being created, may be {@code null}
168	     * @return {@code true} if the city already contains the maximum number of owners
169	     */
170	    private boolean cityAtCapacity(String city) {
171	        if (city == null) {
172	            return false;
173	        }
174	        long ownersInCity = this.clinicService.findAllOwners().stream()
175	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
176	            .count();
177	        return ownersInCity >= MAX_OWNERS_PER_CITY;
178	    }
179	
180	    /**
181	     * Resolves the city to store for a newly created owner. If another owner is already stored in
182	     * the same city (compared ignoring letter case), that existing owner's exact spelling of the
183	     * city name is reused so that a single city is always represented consistently. Otherwise the
184	     * supplied city is title-cased (see {@link #titleCase(String)}) before being stored.
185	     *
186	     * @param city the raw city supplied for the owner being created, may be {@code null}
187	     * @return the city to store, or {@code null} if {@code city} is {@code null}
188	     */
189	    private String resolveCity(String city) {
190	        if (city == null) {
191	            return null;
192	        }
193	        return this.clinicService.findAllOwners().stream()
194	            .map(Owner::getCity)
195	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
196	            .findFirst()
197	            .orElseGet(() -> titleCase(city));
198	    }
199	
200	    /**
201	     * Title-cases a value so that the first letter of every whitespace-separated word is
202	     * upper-cased and every other letter is lower-cased, preserving the original whitespace. For
203	     * example {@code "new  york"} becomes {@code "New  York"} and {@code "LONDON"} becomes
204	     * {@code "London"}.
205	     *
206	     * @param value the raw value, may be {@code null}
207	     * @return the title-cased value, or {@code null} if {@code value} is {@code null}
208	     */
209	    private static String titleCase(String value) {
210	        if (value == null) {
211	            return null;
212	        }
213	        StringBuilder result = new StringBuilder(value.length());
214	        boolean startOfWord = true;
215	        for (int i = 0; i < value.length(); i++) {
216	            char c = value.charAt(i);
217	            if (Character.isWhitespace(c)) {
218	                startOfWord = true;
219	                result.append(c);
220	            } else {
221	                result.append(startOfWord ? Character.toUpperCase(c) : Character.toLowerCase(c));
222	                startOfWord = false;
223	            }
224	        }
225	        return result.toString();
226	    }
227	
228	    /**
229	     * Builds the customer code for a newly created owner in the given city, formatted as
230	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number of owners
231	     * already stored in that city, zero-padded to four digits (e.g. {@code LONDON-0007}). The
232	     * count of existing owners in the city ignores letter case.
233	     *
234	     * @param city the city of the owner being created
235	     * @return the assigned customer code
236	     */
237	    private String nextCustomerCode(String city) {
238	        long ownersInCity = this.clinicService.findAllOwners().stream()
239	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
240	            .count();
241	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
242	    }
243	
244	    /**
245	     * The maximum membership number that still qualifies an owner for the founding tier. The
246	     * first {@value #MAX_FOUNDING_MEMBERS} owners ever created are founding members.
247	     */
248	    private static final int MAX_FOUNDING_MEMBERS = 100;
249	
250	    /**
251	     * Resolves the membership tier for a newly created owner from its sequential membership
252	     * number. The first {@value #MAX_FOUNDING_MEMBERS} owners ever created are {@code FOUNDING};
253	     * every later owner is {@code STANDARD}.
254	     *
255	     * @param membershipNumber the owner's sequential membership number
256	     * @return {@code "FOUNDING"} or {@code "STANDARD"}
257	     */
258	    private static String membershipTierFor(int membershipNumber) {
259	        return membershipNumber <= MAX_FOUNDING_MEMBERS ? "FOUNDING" : "STANDARD";
260	    }
261	
262	    /**
263	     * Counts how many existing owners already share the given last name, ignoring letter case and
264	     * surrounding or repeated whitespace. This is evaluated at the moment a new owner is created,
265	     * before that owner is stored, so it reflects the number of other owners that carry the same
266	     * last name.
267	     *
268	     * @param lastName the last name of the owner being created, may be {@code null}
269	     * @return the number of other owners already sharing that last name
270	     */
271	    private int namesakeCount(String lastName) {
272	        String normalized = normalize(lastName);
273	        return (int) this.clinicService.findAllOwners().stream()
274	            .filter(existing -> Objects.equals(normalize(existing.getLastName()), normalized))
275	            .count();
276	    }
277	
278	    /**
279	     * Determines whether another owner already shares a household with the owner being created,
280	     * meaning an existing owner already has the same address and city. Both address and city are
281	     * compared ignoring letter case and surrounding or repeated whitespace (see
282	     * {@link #normalize(String)}). This is evaluated before the new owner is stored, so it reflects
283	     * only owners that already existed.
284	     *
285	     * @param owner the candidate owner to check
286	     * @return {@code true} if a stored owner already has the same address and city
287	     */
288	    private boolean sharesHousehold(Owner owner) {
289	        String address = normalize(owner.getAddress());
290	        String city = normalize(owner.getCity());
291	        return this.clinicService.findAllOwners().stream()
292	            .anyMatch(existing -> Objects.equals(normalize(existing.getAddress()), address)
293	                && Objects.equals(normalize(existing.getCity()), city));
294	    }
295	
296	    /**
297	     * The locality assigned to an owner whose city is the single most common city among the
298	     * existing owners at the moment of creation.
299	     */
300	    private static final String LOCALITY_LOCAL = "local";
301	
302	    /**
303	     * The locality assigned to an owner whose city is not the single most common city among the
304	     * existing owners at the moment of creation.
305	     */
306	    private static final String LOCALITY_REMOTE = "remote";
307	
308	    /**
309	     * Resolves the locality for a newly created owner. The owner is {@code "local"} when their city
310	     * is the single most common city among the owners that already exist (compared ignoring letter
311	     * case and surrounding or repeated whitespace, see {@link #normalize(String)}); otherwise they
312	     * are {@code "remote"}. If there is no existing owner, or the most common city is shared by a
313	     * tie, or the owner's city is not that single most common city, the owner is {@code "remote"}.
314	     * This is evaluated before the new owner is stored, so it reflects only owners that already
315	     * existed.
316	     *
317	     * @param city the city of the owner being created, may be {@code null}
318	     * @return {@code "local"} or {@code "remote"}
319	     */
320	    private String localityFor(String city) {
321	        if (city == null) {
322	            return LOCALITY_REMOTE;
323	        }
324	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
325	            .map(Owner::getCity)
326	            .filter(Objects::nonNull)
327	            .collect(Collectors.groupingBy(OwnerRestControllerV1::normalize, Collectors.counting()));
328	        if (countsByCity.isEmpty()) {
329	            return LOCALITY_REMOTE;
330	        }
331	        long max = Collections.max(countsByCity.values());
332	        List<String> mostCommon = countsByCity.entrySet().stream()
333	            .filter(entry -> entry.getValue() == max)
334	            .map(Map.Entry::getKey)
335	            .toList();
336	        if (mostCommon.size() != 1) {
337	            return LOCALITY_REMOTE;
338	        }
339	        return mostCommon.get(0).equals(normalize(city)) ? LOCALITY_LOCAL : LOCALITY_REMOTE;
340	    }
341	
342	    /**
343	     * Determines whether an owner already exists using the same telephone number.
344	     * Comparison ignores letter case and surrounding or repeated whitespace.
345	     *
346	     * @param owner the candidate owner to check
347	     * @return {@code true} if any other owner with the same telephone is already stored
348	     */
349	    private boolean ownerAlreadyExists(Owner owner) {
350	        String telephone = normalizeTelephone(owner.getTelephone());
351	        return this.clinicService.findAllOwners().stream()
352	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
353	    }
354	
355	    /**
356	     * Normalizes a telephone number to digits only, stripping spaces, dashes and
357	     * parentheses (any non-digit character). This is the canonical stored form and is
358	     * used for the telephone-uniqueness check, so {@code "(613) 555-0100"} and
359	     * {@code "6135550100"} are treated as the same number.
360	     *
361	     * @param telephone the raw telephone value, may be {@code null}
362	     * @return the digits-only value, or {@code null} if {@code telephone} is {@code null}
363	     */
364	    private static String normalizeTelephone(String telephone) {
365	        if (telephone == null) {
366	            return null;
367	        }
368	        return telephone.replaceAll("[^0-9]", "");
369	    }
370	
371	    /**
372	     * Determines whether another owner already uses the same email address.
373	     * Owners without an email are ignored, so a missing email never conflicts.
374	     * Comparison ignores letter case and surrounding or repeated whitespace.
375	     *
376	     * @param owner the candidate owner to check
377	     * @return {@code true} if the candidate supplies an email already used by a stored owner
378	     */
379	    private boolean emailAlreadyExists(Owner owner) {
380	        String email = normalize(owner.getEmail());
381	        if (email == null || email.isEmpty()) {
382	            return false;
383	        }
384	        return this.clinicService.findAllOwners().stream()
385	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
386	    }
387	
388	    /**
389	     * Normalizes a value for duplicate detection so that comparisons ignore letter
390	     * case and surrounding or repeated whitespace. Leading and trailing whitespace is
391	     * trimmed, any run of internal whitespace is collapsed to a single space, and the
392	     * result is lower-cased. For example {@code "  john   smith "} and {@code "John Smith"}
393	     * both normalize to {@code "john smith"}.
394	     *
395	     * @param value the raw value, may be {@code null}
396	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
397	     */
398	    private static String normalize(String value) {
399	        if (value == null) {
400	            return null;
401	        }
402	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
403	    }
404	
405	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
406	    @Override
407	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
408	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
409	        if (currentOwner == null) {
410	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
411	        }
412	        currentOwner.setAddress(ownerFieldsDto.getAddress());
413	        currentOwner.setCity(ownerFieldsDto.getCity());
414	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
415	        currentOwner.setLastName(ownerFieldsDto.getLastName());
416	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
417	        this.clinicService.saveOwner(currentOwner);
418	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
419	    }
420	
421	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
422	    @Transactional
423	    @Override
424	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
425	        Owner owner = this.clinicService.findOwnerById(ownerId);
426	        if (owner == null) {
427	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
428	        }
429	        this.clinicService.deleteOwner(owner);
430	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
431	    }
432	
433	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
434	    @Override
435	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
436	        Owner owner = this.clinicService.findOwnerById(ownerId);
437	        if (owner == null) {
438	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
439	        }
440	        HttpHeaders headers = new HttpHeaders();
441	        Pet pet = petMapper.toPet(petFieldsDto);
442	        owner.setId(ownerId);
443	        pet.setOwner(owner);
444	        pet.getType().setName(null);
445	        this.clinicService.savePet(pet);
446	        PetDto petDto = petMapper.toPetDto(pet);
447	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
448	            .buildAndExpand(pet.getId()).toUri());
449	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
450	    }
451	
452	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
453	    @Override
454	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
455	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
456	        if (currentOwner != null) {
457	            Pet currentPet = this.clinicService.findPetById(petId);
458	            if (currentPet != null) {
459	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
460	                currentPet.setName(petFieldsDto.getName());
461	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
462	                this.clinicService.savePet(currentPet);
463	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
464	            }
465	        }
466	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
467	    }
468	
469	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
470	    @Override
471	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
472	        HttpHeaders headers = new HttpHeaders();
473	        Visit visit = visitMapper.toVisit(visitFieldsDto);
474	        Pet pet = new Pet();
475	        pet.setId(petId);
476	        visit.setPet(pet);
477	        this.clinicService.saveVisit(visit);
